class SporadicTask:
    def __init__(self, e, d, p):
        self.e = e  # Worst-case execution time
        self.d = d  # Relative deadline
        self.p = p  # Minimum inter-arrival time (period)

def has_implicit_deadlines(task_set):
    for task in task_set:
        if task.d != task.p:
            return False
    return True

def has_constrained_deadlines(task_set):
    for task in task_set:
        if task.d > task.p:
            return False
    return True

def has_arbitrary_deadlines(task_set):
    # This is the default if not implicit or constrained
    return True

class FPScheduler:
    def __init__(self, task_set, priority_ordering):
        self.task_set = task_set
        self.priority_ordering = priority_ordering # Map task_id to priority (higher value = higher priority)
        self.ready_jobs = [] # List of (job, task_priority, release_time)

    def schedule_next_job(self, current_time):
        # 1. Update ready_jobs based on new releases
        # 2. Sort ready_jobs by task_priority (desc) then release_time (asc)
        if self.ready_jobs:
            highest_priority_job = self.ready_jobs[0]
            # Execute highest_priority_job for one time unit
            return highest_priority_job
        return None # No jobs ready

class EDFScheduler:
    def __init__(self, task_set):
        self.task_set = task_set
        self.ready_jobs = [] # List of (job, absolute_deadline, release_time)

    def schedule_next_job(self, current_time):
        # 1. Update ready_jobs based on new releases
        # 2. Sort ready_jobs by absolute_deadline (asc)
        if self.ready_jobs:
            earliest_deadline_job = self.ready_jobs[0]
            # Execute earliest_deadline_job for one time unit
            return earliest_deadline_job
        return None # No jobs ready

def is_fp_schedulable(task_set, priority_ordering):
    # This is a complex analysis, often involving response time calculations
    # For a given task tau_i, calculate its worst-case response time R_i
    # If R_i <= tau_i.d for all tasks tau_i, then it's schedulable.
    for task_i in task_set:
        R_i = calculate_worst_case_response_time_fp(task_i, task_set, priority_ordering)
        if R_i > task_i.d:
            return False
    return True

class SynchronousPeriodicTask:
    def __init__(self, e, d, p):
        self.e = e
        self.d = d
        self.p = p
        self.first_release_time = 0 # All tasks start at 0

def assign_dm_priorities(task_set):
    # Sort tasks by deadline, ascending
    sorted_tasks = sorted(task_set, key=lambda task: task.d)
    priority_map = {}
    current_priority = len(task_set) # Highest priority
    for task in sorted_tasks:
        priority_map[task] = current_priority
        current_priority -= 1
    return priority_map

def assign_rm_priorities(task_set):
    # Sort tasks by period, ascending
    sorted_tasks = sorted(task_set, key=lambda task: task.p)
    priority_map = {}
    current_priority = len(task_set) # Highest priority
    for task in sorted_tasks:
        priority_map[task] = current_priority
        current_priority -= 1
    return priority_map

def calculate_utilization(task_set):
    U_T = 0.0
    for task in task_set:
        U_T += task.e / task.p
    return U_T

import math

def lcm(a, b):
    return (a * b) // math.gcd(a, b)

def calculate_hyperperiod(task_set):
    periods = [task.p for task in task_set]
    if not periods:
        return 0
    result_lcm = periods[0]
    for i in range(1, len(periods)):
        result_lcm = lcm(result_lcm, periods[i])
    return result_lcm

import math

def is_fp_schedulable_ll_bound(task_set):
    if not has_implicit_deadlines(task_set):
        return False # Condition only for implicit deadlines

    U_T = calculate_utilization(task_set)
    n = len(task_set)

    if n == 0:
        return True

    # Original Liu & Layland bound
    ll_bound = n * (2**(1/n) - 1)
    if U_T <= ll_bound:
        return True

    # Simpler, asymptotic bound
    if U_T <= math.log(2):
        return True

    return False # Not guaranteed schedulable by this test

